@Composable fun MentoHomeScreen(data:List<PaymentWithInstallments>,open:(PaymentWithInstallments)->Unit,toggle:(Installment)->Unit,modifier:Modifier){val now=System.currentTimeMillis();val current=PersianDate.from(now);val monthRows=data.mapNotNull{r->r.installments.firstOrNull{val p=PersianDate.from(it.dueAt);p.year==current.year&&p.month==current.month}?.let{r to it}};val openMonth=monthRows.map{it.second}.filter{it.paidAt==null}.sortedBy{it.dueAt};var q by remember{mutableStateOf("")};var f by remember{mutableStateOf("همه")};LazyColumn(modifier.fillMaxSize().padding(horizontal=16.dp),verticalArrangement=Arrangement.spacedBy(9.dp),contentPadding=PaddingValues(bottom=110.dp)){item{Row(Modifier.fillMaxWidth().padding(top=8.dp),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.Bottom){Column{Text(tx("این ماه","This month"),fontSize=23.sp,fontWeight=FontWeight.ExtraBold);Text(tx("پرداخت‌های ${persianMonthName(current.month)}","Payments for ${persianMonthName(current.month)}"),fontSize=12.sp,color=MM)};Text(date(now),fontSize=11.sp,color=MM)}};item{Card(colors=CardDefaults.cardColors(MI),shape=RoundedCornerShape(24.dp),modifier=Modifier.animateContentSize()){Column(Modifier.fillMaxWidth().padding(18.dp)){Text(tx("این‌قدر باید بدی","This is what you owe"),color=Color.White.copy(.68f));Text("${money(openMonth.sumOf{it.amount})} ${tx("تومان","toman")}",color=Color.White,fontSize=27.sp,fontWeight=FontWeight.ExtraBold);Spacer(Modifier.height(14.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(tx("${fa(openMonth.size)} پرداخت این ماه","${fa(openMonth.size)} payments this month"),color=Color.White.copy(.75f));Text(openMonth.firstOrNull()?.let{tx("بعدی: ${date(it.dueAt)}","Next: ${date(it.dueAt)}")}?:tx("این ماه چیزی نمونده ✨","All paid for this month ✨"),color=Color(0xFF83E3C4))}}}};item{OutlinedTextField(q,{q=it},Modifier.fillMaxWidth(),shape=RoundedCornerShape(16.dp),singleLine=true,leadingIcon={Icon(Icons.Outlined.Search,null)},placeholder={Text(tx("جست‌وجوی پرداخت این ماه","Search this month"))})};item{LazyRow(horizontalArrangement=Arrangement.spacedBy(7.dp)){items(listOf("همه","در انتظار","معوق","انجام‌شده")){x->FilterChip(f==x,{f=x},{Text(lx(x))})}}};val shown=monthRows.filter{(r,_)->r.item.title.contains(q,true)||r.item.category.contains(q,true)}.filter{(_,i)->when(f){"در انتظار"->i.paidAt==null&&i.dueAt>=now;"معوق"->i.paidAt==null&&i.dueAt<now;"انجام‌شده"->i.paidAt!=null;else->true}};if(shown.isEmpty())item{Empty(tx("برای این ماه پرداختی در این بخش نیست","No payments in this section for this month"))};items(shown,key={it.first.item.id}){(r,i)->PaymentCard(r,i,{open(r)}){toggle(i)}}}}
@Composable private fun PaymentCard(r:PaymentWithInstallments,i:Installment,open:()->Unit,pay:()->Unit){val done=i.paidAt!=null;Card(onClick=open,shape=RoundedCornerShape(18.dp),colors=CardDefaults.cardColors(MaterialTheme.colorScheme.surface),border=BorderStroke(1.dp,if(done)MT.copy(.45f) else MaterialTheme.colorScheme.outline),modifier=Modifier.animateContentSize()){Row(Modifier.fillMaxWidth().padding(12.dp),verticalAlignment=Alignment.CenterVertically){Surface(color=if(done)MT.copy(.12f) else MS,shape=RoundedCornerShape(14.dp),modifier=Modifier.size(44.dp)){Box(contentAlignment=Alignment.Center){Icon(icon(r.item.iconKey),null,tint=if(done)MT else MP)}};Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text(r.item.title,fontWeight=FontWeight.Bold);Text(if(done)tx("انجام شد · ${date(i.dueAt)}","Paid · ${date(i.dueAt)}") else "${lx(r.item.category)} · ${date(i.dueAt)}",fontSize=11.sp,color=if(done)MT else if(i.dueAt<System.currentTimeMillis())MR else MM);Text("${money(i.amount)} ${tx("تومان","toman")}",fontSize=12.sp,fontWeight=FontWeight.SemiBold)};Surface(onClick=pay,shape=CircleShape,color=if(done)MT else MaterialTheme.colorScheme.surface,border=BorderStroke(1.5.dp,if(done)MT else MP),modifier=Modifier.size(36.dp)){Box(contentAlignment=Alignment.Center){Icon(Icons.Outlined.Done,if(done)tx("انجام شده","Paid") else tx("ثبت پرداخت","Mark as paid"),tint=if(done)Color.White else MP,modifier=Modifier.size(19.dp))}}}}}

