  LazyColumn(Modifier.heightIn(max=460.dp)){
   icons.groupBy{it.group}.forEach{(g,list)->
    item{Text(lx(g),fontWeight=FontWeight.Bold,color=MM,modifier=Modifier.padding(vertical=8.dp))}
    item{list.chunked(4).forEach{r->Row{r.forEach{x->Column(Modifier.weight(1f).clickable{choose(x.key)}.padding(6.dp),horizontalAlignment=Alignment.CenterHorizontally){Surface(color=if(selected==x.key)MP else MS,shape=RoundedCornerShape(12.dp),modifier=Modifier.size(44.dp)){Box(contentAlignment=Alignment.Center){Icon(x.image,null,tint=if(selected==x.key)Color.White else MP)}};Text(lx(x.label),fontSize=9.sp)}};repeat(4-r.size){Spacer(Modifier.weight(1f))}}}}
