@Composable private fun DateDialog(initial:PersianDate,dismiss:()->Unit,choose:(PersianDate)->Unit){
 var y by remember{mutableIntStateOf(initial.year)};var m by remember{mutableIntStateOf(initial.month)};var d by remember{mutableIntStateOf(initial.day)}
 AlertDialog(onDismissRequest=dismiss,title={Text(tx("انتخاب تاریخ شمسی","Choose Persian date"))},text={Column{MonthNav(y,m,{if(m==1){m=12;y--}else m--},{if(m==12){m=1;y++}else m++});Grid(y,m,d,emptySet()){d=it}}},confirmButton={Button({choose(PersianDate(y,m,d.coerceAtMost(persianMonthDays(y,m))))}){Text(tx("تأیید","Confirm"))}},dismissButton={TextButton(dismiss){Text(tx("انصراف","Cancel"))}})
}

