@Composable fun MentoCalendarScreen(data:List<PaymentWithInstallments>,open:(PaymentWithInstallments)->Unit,modifier:Modifier){var s by remember{mutableStateOf(PersianDate.from())};var y by remember{mutableIntStateOf(s.year)};var m by remember{mutableIntStateOf(s.month)};val dots=data.flatMap{it.installments}.map{PersianDate.from(it.dueAt)}.filter{it.year==y&&it.month==m}.map{it.day}.toSet();val due=data.mapNotNull{r->r.installments.firstOrNull{PersianDate.from(it.dueAt)==s}?.let{r to it}};LazyColumn(modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp),contentPadding=PaddingValues(bottom=90.dp)){item{Text(tx("تقویم پرداخت","Payment calendar"),fontSize=23.sp,fontWeight=FontWeight.ExtraBold);Text(tx("روزهای دورخط‌دار دارای سررسید هستند","Outlined days have payments"),fontSize=12.sp,color=MM)};item{Card(shape=RoundedCornerShape(22.dp),colors=CardDefaults.cardColors(MaterialTheme.colorScheme.surface),border=BorderStroke(1.dp,MaterialTheme.colorScheme.outline)){Column(Modifier.padding(12.dp)){MonthNav(y,m,{if(m==1){m=12;y--}else m--},{if(m==12){m=1;y++}else m++});Grid(y,m,if(s.year==y&&s.month==m)s.day else -1,dots){s=PersianDate(y,m,it)}}}};item{Text(tx("موعدهای ${date(s.toMillis())}","Payments due ${date(s.toMillis())}"),fontWeight=FontWeight.Bold)};if(due.isEmpty())item{Empty(tx("برای این روز موعدی ثبت نشده","No payments due on this day"))};items(due,key={it.second.id}){(r,i)->PaymentCard(r,i,{open(r)},{})}}}
@Composable private fun MonthNav(y:Int,m:Int,prev:()->Unit,next:()->Unit){Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween,verticalAlignment=Alignment.CenterVertically){IconButton(prev){Icon(Icons.Outlined.ChevronRight,null)};Text("${persianMonthName(m)} ${fa(y)}",fontWeight=FontWeight.Bold);IconButton(next){Icon(Icons.Outlined.ChevronLeft,null)}}}
@Composable private fun Grid(y:Int,m:Int,selected:Int,dots:Set<Int>,choose:(Int)->Unit){
 Row{(if(AppLanguage.code=="en")listOf("Sa","Su","Mo","Tu","We","Th","Fr")else listOf("ش","ی","د","س","چ","پ","ج")).forEach{Text(it,Modifier.weight(1f),textAlign=TextAlign.Center,fontSize=10.sp,color=MM)}}
 val first=Calendar.getInstance().apply{timeInMillis=PersianDate(y,m,1).toMillis()};val off=first.get(Calendar.DAY_OF_WEEK)%7
 repeat(6){w->Row{repeat(7){c->val d=w*7+c-off+1;if(d in 1..persianMonthDays(y,m))Surface(onClick={choose(d)},shape=CircleShape,color=if(d==selected)MP else Color.Transparent,border=if(d in dots&&d!=selected)BorderStroke(1.5.dp,MT)else null,modifier=Modifier.weight(1f).padding(2.dp).aspectRatio(1f)){Box(contentAlignment=Alignment.Center){Text(fa(d),fontSize=12.sp,color=if(d==selected)Color.White else MaterialTheme.colorScheme.onSurface)}}else Spacer(Modifier.weight(1f).aspectRatio(1f))}}}
}

@Composable fun MentoReportScreen(data:List<PaymentWithInstallments>,modifier:Modifier){var range by remember{mutableStateOf("ماهانه")};val now=System.currentTimeMillis();val days=when(range){"۷ روزه"->7;"سه‌ماهه"->90;"سالانه"->365;else->30};val start=now-days*86_400_000L;val paid=data.flatMap{r->r.installments.filter{it.paidAt!=null&&it.paidAt!!>=start}.map{r.item.category to it}};val total=paid.sumOf{it.second.amount};val cats=paid.groupBy{it.first}.mapValues{e->e.value.sumOf{it.second.amount}}.toList().sortedByDescending{it.second};val upcoming=data.flatMap{it.installments}.filter{it.paidAt==null&&it.dueAt in now..now+days*86_400_000L}.sumOf{it.amount};LazyColumn(modifier.fillMaxSize().padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp),contentPadding=PaddingValues(bottom=90.dp)){item{Text(tx("تحلیل مالی","Financial insights"),fontSize=23.sp,fontWeight=FontWeight.ExtraBold);Text(tx("الگوی پرداخت و تعهدهای پیش‌رو","Payment activity and upcoming commitments"),fontSize=12.sp,color=MM)};item{LazyRow(horizontalArrangement=Arrangement.spacedBy(7.dp)){items(listOf("۷ روزه","ماهانه","سه‌ماهه","سالانه")){x->FilterChip(range==x,{range=x},{Text(lx(x))})}}};item{Card(colors=CardDefaults.cardColors(MI),shape=RoundedCornerShape(24.dp)){Column(Modifier.fillMaxWidth().padding(18.dp)){Text(tx("پرداخت‌شده در بازه","Paid during this period"),color=Color.White.copy(.65f));Text("${money(total)} ${tx("تومان","toman")}",color=Color.White,fontSize=27.sp,fontWeight=FontWeight.ExtraBold);Spacer(Modifier.height(12.dp));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(tx("${fa(paid.size)} تراکنش","${fa(paid.size)} transactions"),color=Color.White.copy(.7f));Text(tx("${money(upcoming)} تومان پیش‌رو","${money(upcoming)} toman upcoming"),color=Color(0xFF83E3C4))}}}};item{Text(tx("ترکیب هزینه‌ها","Expense breakdown"),fontWeight=FontWeight.Bold,fontSize=16.sp)};if(cats.isEmpty())item{Empty(tx("در این بازه پرداخت ثبت‌شده‌ای ندارید","No payments recorded during this period"))}else{item{Donut(cats,total)};items(cats){(cat,v)->val p=if(total==0L)0f else v.toFloat()/total;Column{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(lx(cat),fontWeight=FontWeight.SemiBold);Text(tx("${money(v)} تومان · ${fa((p*100).toInt())}٪","${money(v)} toman · ${fa((p*100).toInt())}%"),fontSize=11.sp,color=MM)};LinearProgressIndicator(p,Modifier.fillMaxWidth().padding(top=6.dp).height(7.dp),color=MP,trackColor=MS)}}}}}
@Composable private fun Donut(data:List<Pair<String,Long>>,total:Long){val cs=listOf(MP,MT,Color(0xFFF0A83B),Color(0xFF8A62D6),Color(0xFFDF6577));Card(shape=RoundedCornerShape(20.dp),colors=CardDefaults.cardColors(MaterialTheme.colorScheme.surface),border=BorderStroke(1.dp,MaterialTheme.colorScheme.outline)){Row(Modifier.fillMaxWidth().padding(16.dp),verticalAlignment=Alignment.CenterVertically){Canvas(Modifier.size(118.dp)){var start=-90f;data.take(5).forEachIndexed{i,p->val sw=if(total==0L)0f else p.second*360f/total;drawArc(cs[i%cs.size],start,sw,false,style=androidx.compose.ui.graphics.drawscope.Stroke(18.dp.toPx(),cap=StrokeCap.Round));start+=sw}};Spacer(Modifier.width(18.dp));Column(verticalArrangement=Arrangement.spacedBy(7.dp)){data.take(5).forEachIndexed{i,p->Row(verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(8.dp).background(cs[i%cs.size],CircleShape));Spacer(Modifier.width(7.dp));Text(lx(p.first),fontSize=12.sp)}}}}}}

